declare module "bun" {
  interface Subprocess { readonly exited: Promise<number>; readonly pid: number; readonly exitCode: number | null; readonly killed: boolean; kill(signal?: string | number): void; stdout: ReadableStream<Uint8Array>; stderr: ReadableStream<Uint8Array>; }
  interface SpawnOptions { stdin?: "ignore" | "inherit" | "pipe"; stdout?: "ignore" | "inherit" | "pipe"; stderr?: "ignore" | "inherit" | "pipe"; cwd?: string; env?: Record<string, string | undefined>; timeout?: number; }
  function spawn(argv: readonly string[], options?: SpawnOptions): Subprocess;
  function spawn(options: SpawnOptions & { cmd: readonly string[] }): Subprocess;
}
